create table if not exists public.exercise_guides (
  exercise_id text primary key references public.exercises(id) on delete cascade,
  guide jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.exercise_guides enable row level security;
drop policy if exists "guias legibles por usuarios" on public.exercise_guides;
create policy "guias legibles por usuarios" on public.exercise_guides for select to authenticated using (true);
on conflict (exercise_id) do update set guide=excluded.guide, updated_at=now();

