insert into public.exercise_guides (exercise_id, guide) values
('back-extension','{"id":"back-extension","nombre":"Hiperextensión lumbar","musculo_principal":"Erectores espinales","musculos_secundarios":["Glúteo mayor","Isquiotibiales"],"nivel":"principiante","preparacion":"Ajusta el apoyo justo por debajo de la cadera, que pueda doblarse libre. Pies bien anclados y brazos cruzados en el pecho.","fases":[{"fase":"Baja","cue":"Dobla desde la cadera con la espalda larga, sin prisa."},{"fase":"Sube","cue":"Aprieta glúteo y sube hasta alinear tronco y piernas."},{"fase":"Aguanta","cue":"Un segundo arriba, sin pasarte de la línea."}],"respiracion":"Coge aire al bajar, suéltalo al subir.","errores":["Arquear la lumbar arriba: para cuando tronco y piernas formen una línea.","Rebotar abajo: baja controlado y sube sin impulso.","Apoyo demasiado alto: bájalo hasta que la cadera quede libre para doblarse."],"mas_facil":"superman","mas_dificil":"good-morning","sin_material":"superman","vista_animacion":"lateral","seguridad":"Si notas dolor lumbar, reduce el recorrido y no subas por encima de la línea del cuerpo."}'::jsonb),
('barbell-row','{"id":"barbell-row","nombre":"Remo con barra","musculo_principal":"Dorsal ancho","musculos_secundarios":["Trapecio medio","Romboides","Deltoides posterior","Bíceps","Erectores espinales"],"nivel":"intermedio","preparacion":"Pies a la anchura de cadera, agarre algo más ancho que los hombros. Dobla la cadera hasta dejar el tronco a unos 45 grados, espalda neutra y rodillas suaves.","fases":[{"fase":"Tira","cue":"Lleva la barra hacia el ombligo, codos atrás."},{"fase":"Aprieta","cue":"Junta las escápulas un instante arriba."},{"fase":"Baja","cue":"Estira los brazos controlando, sin mover el tronco."}],"respiracion":"Coge aire abajo, suéltalo al terminar el tirón.","errores":["Espalda redonda: pecho abierto y columna larga; si no puedes, baja el peso.","Levantar el tronco para mover la barra: fija el ángulo y tira con la espalda.","Codos muy abiertos hacia el pecho: codos cerca del cuerpo, barra al ombligo."],"mas_facil":"dumbbell-row","mas_dificil":null,"sin_material":null,"vista_animacion":"lateral","seguridad":"Si la lumbar se cansa antes que la espalda, pasa al remo con mancuerna con apoyo."}'::jsonb),
('chin-up','{"id":"chin-up","nombre":"Dominadas supinas","musculo_principal":"Dorsal ancho","musculos_secundarios":["Bíceps","Braquial","Romboides","Trapecio inferior","Core"],"nivel":"intermedio","preparacion":"Agarre con las palmas hacia ti, a la anchura de hombros. Cuélgate con los brazos estirados y los hombros lejos de las orejas.","fases":[{"fase":"Tira","cue":"Pecho hacia la barra, codos hacia abajo y atrás."},{"fase":"Arriba","cue":"Barbilla por encima de la barra, cuello neutro."},{"fase":"Baja","cue":"Controla hasta estirar los brazos del todo."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Balancearte para subir: aprieta glúteos y abdomen, piernas quietas.","Medias repeticiones: estira los brazos abajo en cada repetición.","Estirar el cuello hacia la barra: sube el pecho, no la barbilla."],"mas_facil":"lat-pulldown","mas_dificil":"pull-up","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('dead-hang','{"id":"dead-hang","nombre":"Colgarse en barra (dead hang)","musculo_principal":"Antebrazo (agarre)","musculos_secundarios":["Dorsal ancho","Manguito rotador","Core"],"nivel":"principiante","preparacion":"Agarra la barra con las palmas hacia delante, a la anchura de hombros y con el pulgar rodeándola. Sube a un cajón si hace falta y cuélgate sin saltar.","fases":[{"fase":"Cuélgate","cue":"Brazos estirados; deja que el cuerpo pese sin soltarte de golpe."},{"fase":"Aguanta","cue":"Cuerpo quieto, piernas juntas, respira."},{"fase":"Sal","cue":"Apoya los pies antes de soltar las manos."}],"respiracion":"Respira lento y continuo; no aguantes el aire.","errores":["Balancearte: aprieta abdomen y glúteos y quédate quieto.","Pulgar suelto: rodea la barra con el pulgar para no resbalar.","Soltarte de golpe al final: busca el apoyo con los pies primero."],"mas_facil":null,"mas_dificil":"pull-up","sin_material":null,"vista_animacion":"lateral","seguridad":"Si notas dolor en el hombro, baja y apoya parte del peso en los pies."}'::jsonb),
('dumbbell-row','{"id":"dumbbell-row","nombre":"Remo con mancuerna a una mano","musculo_principal":"Dorsal ancho","musculos_secundarios":["Romboides","Trapecio medio","Deltoides posterior","Bíceps"],"nivel":"principiante","preparacion":"Rodilla y mano del mismo lado sobre el banco, la otra pierna firme en el suelo. Espalda plana y mancuerna colgando bajo el hombro.","fases":[{"fase":"Tira","cue":"Lleva la mancuerna hacia la cadera, codo pegado al cuerpo."},{"fase":"Baja","cue":"Estira el brazo del todo y deja que el hombro baje un poco."}],"respiracion":"Suelta el aire al tirar, cógelo al bajar.","errores":["Girar el tronco para subir el peso: hombros paralelos al suelo; baja la carga.","Tirar hacia el pecho: dirige el codo hacia la cadera.","Encoger el hombro: aléjalo de la oreja antes de tirar."],"mas_facil":"machine-row","mas_dificil":"barbell-row","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('inverted-row','{"id":"inverted-row","nombre":"Remo invertido","musculo_principal":"Dorsal ancho","musculos_secundarios":["Romboides","Trapecio medio","Deltoides posterior","Bíceps","Core"],"nivel":"principiante","preparacion":"Barra fija a la altura de la cadera; túmbate debajo con agarre algo más ancho que los hombros. Cuerpo recto de talones a cabeza: cuanto más vertical, más fácil.","fases":[{"fase":"Tira","cue":"Pecho a la barra, codos atrás."},{"fase":"Baja","cue":"Estira los brazos controlando, sin romper la línea del cuerpo."}],"respiracion":"Suelta el aire al tirar, cógelo al bajar.","errores":["Cadera caída: aprieta glúteos y abdomen, cuerpo como una tabla.","Adelantar la barbilla: lleva el pecho a la barra, no la cara.","Medio recorrido: estira los brazos del todo abajo."],"mas_facil":null,"mas_dificil":"chin-up","sin_material":null,"vista_animacion":"lateral","seguridad":"Usa una barra fija y estable, nunca una superficie que pueda moverse."}'::jsonb),
('lat-pulldown','{"id":"lat-pulldown","nombre":"Jalón al pecho en polea","musculo_principal":"Dorsal ancho","musculos_secundarios":["Redondo mayor","Romboides","Bíceps","Trapecio inferior"],"nivel":"principiante","preparacion":"Ajusta el rodillo para que fije los muslos. Agarre prono algo más ancho que los hombros, pecho alto y ligera inclinación atrás.","fases":[{"fase":"Tira","cue":"Barra a la parte alta del pecho, codos hacia abajo."},{"fase":"Sube","cue":"Deja subir la barra controlando hasta estirar los brazos."}],"respiracion":"Suelta el aire al tirar, cógelo al subir.","errores":["Echarte muy atrás para bajar la barra: inclinación mínima, tira con la espalda.","Tirar por detrás de la nuca: siempre por delante, hacia el pecho.","Soltar arriba de golpe: controla la subida, que el peso no te levante."],"mas_facil":null,"mas_dificil":"chin-up","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('machine-row','{"id":"machine-row","nombre":"Remo en máquina","musculo_principal":"Dorsal ancho","musculos_secundarios":["Romboides","Trapecio medio","Deltoides posterior","Bíceps"],"nivel":"principiante","preparacion":"Ajusta el asiento para que las asas queden a la altura del pecho bajo. Pecho contra el apoyo y brazos estirados.","fases":[{"fase":"Tira","cue":"Codos atrás y junta las escápulas al final."},{"fase":"Vuelve","cue":"Estira los brazos despacio, sin despegar el pecho."}],"respiracion":"Suelta el aire al tirar, cógelo al volver.","errores":["Despegar el pecho del apoyo: quédate pegado y tira con la espalda.","Encoger los hombros: hombros abajo antes de cada tirón.","Tirar a tirones: ritmo constante y pausa corta atrás."],"mas_facil":null,"mas_dificil":"dumbbell-row","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('pull-up','{"id":"pull-up","nombre":"Dominadas","musculo_principal":"Dorsal ancho","musculos_secundarios":["Redondo mayor","Romboides","Trapecio inferior","Bíceps","Braquial","Core"],"nivel":"intermedio","preparacion":"Agarre con las palmas hacia delante, algo más ancho que los hombros. Cuélgate con los brazos estirados y los hombros activos.","fases":[{"fase":"Tira","cue":"Codos hacia los bolsillos, pecho hacia la barra."},{"fase":"Arriba","cue":"Barbilla por encima de la barra, cuello neutro."},{"fase":"Baja","cue":"Controla hasta estirar los brazos del todo."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Patada o balanceo: aprieta glúteos y abdomen, piernas quietas.","Rango corto: brazos estirados abajo, barbilla sobre la barra arriba.","Hombros en las orejas al arrancar: baja los hombros antes de doblar los codos."],"mas_facil":"chin-up","mas_dificil":null,"sin_material":null,"vista_animacion":"ambas","seguridad":null}'::jsonb),
('superman','{"id":"superman","nombre":"Superman","musculo_principal":"Erectores espinales","musculos_secundarios":["Glúteo mayor","Isquiotibiales","Trapecio","Deltoides posterior"],"nivel":"principiante","preparacion":"Boca abajo, brazos estirados al frente y piernas estiradas. Mirada al suelo.","fases":[{"fase":"Sube","cue":"Eleva brazos, pecho y piernas unos centímetros, alargándote."},{"fase":"Aguanta","cue":"Dos segundos arriba, glúteos apretados."},{"fase":"Baja","cue":"Baja despacio y suelta."}],"respiracion":"Suelta el aire al subir y respira normal mientras aguantas.","errores":["Levantar la cabeza para mirar al frente: cuello largo, mirada al suelo.","Subir demasiado y cargar la lumbar: busca alargarte, no arquearte.","Rebotar: sube, aguanta y baja con control."],"mas_facil":null,"mas_dificil":"back-extension","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('barbell-curl','{"id":"barbell-curl","nombre":"Curl bíceps con barra","musculo_principal":"Bíceps","musculos_secundarios":["Braquial","Braquiorradial"],"nivel":"principiante","preparacion":"De pie, pies a la anchura de cadera. Agarre con palmas hacia delante a la anchura de hombros, codos pegados al cuerpo.","fases":[{"fase":"Sube","cue":"Dobla los codos sin moverlos de sitio."},{"fase":"Baja","cue":"Estira los brazos del todo, despacio."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Balancear el tronco: quieto y con glúteos apretados; baja el peso.","Adelantar los codos arriba: codos fijos a los lados.","Bajar a medias: estira el brazo del todo abajo."],"mas_facil":"dumbbell-curl","mas_dificil":null,"sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('dumbbell-curl','{"id":"dumbbell-curl","nombre":"Curl bíceps con mancuernas","musculo_principal":"Bíceps","musculos_secundarios":["Braquial","Braquiorradial"],"nivel":"principiante","preparacion":"De pie o sentado, mancuernas a los lados con las palmas hacia delante. Codos pegados al cuerpo.","fases":[{"fase":"Sube","cue":"Dobla los codos sin moverlos; puedes alternar brazos."},{"fase":"Baja","cue":"Estira del todo en dos o tres segundos."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Impulso con la espalda: tronco quieto; baja el peso.","Muñeca doblada: muñeca recta, en línea con el antebrazo.","Dejar caer el peso: baja en dos o tres segundos."],"mas_facil":null,"mas_dificil":"barbell-curl","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('hammer-curl','{"id":"hammer-curl","nombre":"Curl martillo","musculo_principal":"Braquial","musculos_secundarios":["Braquiorradial","Bíceps"],"nivel":"principiante","preparacion":"De pie, mancuernas a los lados con las palmas mirándose entre sí. Codos pegados al cuerpo.","fases":[{"fase":"Sube","cue":"Dobla los codos con el agarre neutro todo el recorrido."},{"fase":"Baja","cue":"Estira del todo, controlando."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Girar la muñeca: palma mirando hacia dentro de principio a fin.","Adelantar los codos: codos fijos junto al cuerpo.","Balancear el tronco: quieto; baja el peso."],"mas_facil":null,"mas_dificil":null,"sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('seated-calf','{"id":"seated-calf","nombre":"Gemelo sentado","musculo_principal":"Sóleo","musculos_secundarios":["Gemelos"],"nivel":"principiante","preparacion":"Siéntate con el apoyo sobre los muslos, justo por encima de las rodillas. Parte delantera del pie en la plataforma, talones libres.","fases":[{"fase":"Baja","cue":"Deja caer los talones hasta notar el estiramiento."},{"fase":"Sube","cue":"Sube sobre la punta de los pies todo lo que puedas."},{"fase":"Aguanta","cue":"Un segundo arriba."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Rebotar abajo: pausa breve en el estiramiento.","Recorrido corto: baja y sube todo lo que da el tobillo.","Apoyar el centro del pie: apoya la parte delantera, talones fuera."],"mas_facil":null,"mas_dificil":null,"sin_material":"standing-calf-raise","vista_animacion":"lateral","seguridad":null}'::jsonb),
('standing-calf-raise','{"id":"standing-calf-raise","nombre":"Elevación de talones de pie","musculo_principal":"Gemelos","musculos_secundarios":["Sóleo"],"nivel":"principiante","preparacion":"De pie, parte delantera del pie sobre un escalón y talones en el aire. Apóyate en la pared para el equilibrio.","fases":[{"fase":"Baja","cue":"Talones abajo hasta notar el estiramiento."},{"fase":"Sube","cue":"Sube sobre la punta de los pies, rodillas estiradas."},{"fase":"Aguanta","cue":"Un segundo arriba."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Doblar las rodillas para empujar: rodillas estiradas, sin bloquearlas.","Rebotar: pausa arriba y abajo.","Peso hacia el borde exterior del pie: empuja con el dedo gordo y el segundo."],"mas_facil":null,"mas_dificil":null,"sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('cardio-steady','{"id":"cardio-steady","nombre":"Cardio zona 2 (correr / bici / elíptica)","musculo_principal":"Sistema cardiorrespiratorio","musculos_secundarios":["Cuádriceps","Glúteos","Isquiotibiales","Gemelos"],"nivel":"principiante","preparacion":"Elige correr, bici o elíptica y un ritmo que puedas sostener de 30 a 60 minutos. Si usas pulsómetro, la zona 2 suele caer en torno al 60-70 % de tu frecuencia máxima.","fases":[{"fase":"Calienta","cue":"Cinco minutos suaves, subiendo poco a poco."},{"fase":"Ritmo","cue":"Puedes hablar en frases completas, pero no cantar. Esfuerzo 3-4 sobre 10."},{"fase":"Vuelve a la calma","cue":"Últimos cinco minutos, más suave."}],"respiracion":"Relajada, por nariz y boca; si no puedes hablar, baja el ritmo.","errores":["Ir demasiado rápido: si no puedes decir una frase entera, baja el ritmo.","Cambiar de intensidad a cada rato: busca un esfuerzo constante.","Colgarte de las asas o del manillar: apóyate sin cargar peso, hombros sueltos."],"mas_facil":null,"mas_dificil":null,"sin_material":"running-outdoor","vista_animacion":"lateral","seguridad":"Para si notas dolor en el pecho, mareo o una falta de aire desproporcionada."}'::jsonb),
('hiking-session','{"id":"hiking-session","nombre":"Sesión de senderismo","musculo_principal":"Sistema cardiorrespiratorio","musculos_secundarios":["Cuádriceps","Glúteos","Gemelos","Isquiotibiales"],"nivel":"principiante","preparacion":"Calzado con buen agarre, agua y la ruta revisada antes de salir. Mochila ajustada a la cadera, no a los hombros.","fases":[{"fase":"Subida","cue":"Pasos cortos y un ritmo que te deje hablar."},{"fase":"Llano","cue":"Zancada natural, mirada unos metros por delante."},{"fase":"Bajada","cue":"Rodillas algo dobladas, pasos cortos y controlados."}],"respiracion":"Si en la subida no puedes hablar, acorta el paso antes de parar.","errores":["Salir demasiado rápido: los primeros 15 minutos, suave.","Bajar con las piernas rígidas: dobla un poco las rodillas y acorta el paso.","Mochila colgando de los hombros: aprieta el cinturón de cadera."],"mas_facil":null,"mas_dificil":"running-outdoor","sin_material":null,"vista_animacion":"lateral","seguridad":"Revisa el tiempo y deja dicho tu ruta antes de salir."}'::jsonb),
('running-outdoor','{"id":"running-outdoor","nombre":"Carrera exterior","musculo_principal":"Sistema cardiorrespiratorio","musculos_secundarios":["Cuádriceps","Glúteos","Gemelos","Isquiotibiales"],"nivel":"principiante","preparacion":"Zapatillas de correr y ruta conocida. Cuerpo alto, mirada al frente y brazos a unos 90 grados.","fases":[{"fase":"Calienta","cue":"Cinco minutos de trote muy suave."},{"fase":"Ritmo","cue":"La mayor parte del tiempo, a ritmo de conversación."},{"fase":"Pisada","cue":"Pasos cortos y rápidos, pie bajo la cadera; entre 160 y 180 pasos por minuto es la referencia habitual."}],"respiracion":"Relajada, por nariz y boca, acompasada con los pasos.","errores":["Zancada larga con el talón muy por delante: acorta el paso y sube la cadencia.","Salir demasiado rápido: los primeros minutos, más lento de lo que te pide el cuerpo.","Hombros tensos y brazos cruzando el cuerpo: suelta los hombros, brazos adelante y atrás."],"mas_facil":"cardio-steady","mas_dificil":null,"sin_material":null,"vista_animacion":"lateral","seguridad":"Sube el volumen poco a poco. Para si notas dolor en el pecho, mareo o un dolor articular que va a más."}'::jsonb),
('bench-press-barbell','{"id":"bench-press-barbell","nombre":"Press banca con barra","musculo_principal":"Pectoral mayor","musculos_secundarios":["Deltoides anterior","Tríceps"],"nivel":"intermedio","preparacion":"Túmbate con los ojos bajo la barra y los pies firmes en el suelo. Escápulas juntas y abajo, agarre algo más ancho que los hombros.","fases":[{"fase":"Baja","cue":"Barra a la parte baja del pecho, codos a unos 45 grados del cuerpo."},{"fase":"Empuja","cue":"Hacia arriba y un poco hacia atrás, hasta estirar los brazos."}],"respiracion":"Coge aire arriba y baja con él; suéltalo al pasar el punto duro.","errores":["Codos abiertos en cruz: acércalos al cuerpo, unos 45 grados.","Rebotar la barra en el pecho: toca con control y empuja.","Despegar el glúteo del banco: glúteos apoyados, empuja el suelo con las piernas."],"mas_facil":"chest-press-machine","mas_dificil":null,"sin_material":"push-up","vista_animacion":"lateral","seguridad":"Usa barras de seguridad o un compañero cuando la carga sea alta."}'::jsonb),
('cable-fly','{"id":"cable-fly","nombre":"Cable fly (cruce de poleas)","musculo_principal":"Pectoral mayor","musculos_secundarios":["Deltoides anterior"],"nivel":"principiante","preparacion":"Poleas a la altura de los hombros y un paso al frente con los pies escalonados. Codos ligeramente doblados y fijos.","fases":[{"fase":"Junta","cue":"Como abrazando un árbol: manos al frente, a la altura del pecho."},{"fase":"Abre","cue":"Vuelve despacio hasta notar el estiramiento, sin pasarte."}],"respiracion":"Suelta el aire al juntar, cógelo al abrir.","errores":["Doblar y estirar los codos: ángulo fijo, el movimiento sale del hombro.","Abrir demasiado: para cuando las manos queden a la altura del cuerpo.","Inclinar el tronco para ayudarte: postura quieta; baja el peso."],"mas_facil":"pec-deck","mas_dificil":null,"sin_material":"push-up","vista_animacion":"frontal","seguridad":null}'::jsonb),
('chest-press-machine','{"id":"chest-press-machine","nombre":"Press de pecho en máquina","musculo_principal":"Pectoral mayor","musculos_secundarios":["Deltoides anterior","Tríceps"],"nivel":"principiante","preparacion":"Ajusta el asiento para que las asas queden a la altura del pecho medio. Espalda pegada al respaldo, escápulas atrás.","fases":[{"fase":"Empuja","cue":"Estira los brazos sin bloquear los codos."},{"fase":"Vuelve","cue":"Controla hasta que las manos queden a la altura del pecho."}],"respiracion":"Suelta el aire al empujar, cógelo al volver.","errores":["Asiento mal ajustado: asas a la altura del pecho, no de los hombros.","Despegar la espalda: hombros y espalda pegados al respaldo.","Soltar el peso en la vuelta: controla hasta el final, sin que choquen las placas."],"mas_facil":null,"mas_dificil":"bench-press-barbell","sin_material":"push-up","vista_animacion":"lateral","seguridad":null}'::jsonb),
('dips-chest','{"id":"dips-chest","nombre":"Fondos en paralelas (pecho)","musculo_principal":"Pectoral mayor","musculos_secundarios":["Tríceps","Deltoides anterior"],"nivel":"intermedio","preparacion":"Sube a las paralelas con los brazos estirados y los hombros abajo. Tronco algo inclinado hacia delante, piernas un poco atrás.","fases":[{"fase":"Baja","cue":"Dobla los codos hasta que el hombro quede a la altura del codo."},{"fase":"Sube","cue":"Empuja hasta estirar los brazos, sin bloquear."}],"respiracion":"Coge aire al bajar, suéltalo al subir.","errores":["Bajar demasiado: para cuando el hombro llegue a la altura del codo.","Hombros hacia las orejas: empuja las paralelas hacia abajo.","Codos muy abiertos: apúntalos atrás y un poco hacia fuera."],"mas_facil":"push-up","mas_dificil":null,"sin_material":"push-up","vista_animacion":"lateral","seguridad":"Si notas molestia en la parte delantera del hombro, reduce el recorrido."}'::jsonb),
('incline-bench-dumbbell','{"id":"incline-bench-dumbbell","nombre":"Press inclinado con mancuernas","musculo_principal":"Pectoral mayor (porción superior)","musculos_secundarios":["Deltoides anterior","Tríceps"],"nivel":"principiante","preparacion":"Banco a unos 30 grados, mancuernas a la altura del pecho. Escápulas juntas y pies firmes en el suelo.","fases":[{"fase":"Empuja","cue":"Sube las mancuernas sobre el pecho, sin chocarlas."},{"fase":"Baja","cue":"Hasta que los codos queden algo por debajo del banco, antebrazos verticales."}],"respiracion":"Suelta el aire al empujar, cógelo al bajar.","errores":["Banco demasiado inclinado: por encima de 45 grados trabaja más el hombro; déjalo en unos 30.","Codos en cruz: acércalos al cuerpo, unos 45 grados.","Perder el control abajo: baja en dos segundos, antebrazos verticales."],"mas_facil":"chest-press-machine","mas_dificil":null,"sin_material":"push-up","vista_animacion":"lateral","seguridad":"Sube y baja las mancuernas apoyándolas en los muslos; no las sueltes a los lados con los brazos estirados."}'::jsonb),
('pec-deck','{"id":"pec-deck","nombre":"Contractora (pec deck)","musculo_principal":"Pectoral mayor","musculos_secundarios":["Deltoides anterior"],"nivel":"principiante","preparacion":"Asiento con las asas a la altura del pecho. Espalda pegada al respaldo y codos ligeramente doblados.","fases":[{"fase":"Junta","cue":"Cierra los brazos delante del pecho y aprieta un segundo."},{"fase":"Abre","cue":"Vuelve despacio hasta notar el estiramiento, sin pasarte."}],"respiracion":"Suelta el aire al juntar, cógelo al abrir.","errores":["Asiento demasiado alto o bajo: asas a la altura del pecho, no del cuello.","Despegar la espalda para cerrar: espalda pegada; baja el peso.","Abrir demasiado: para cuando los codos queden en línea con el cuerpo."],"mas_facil":null,"mas_dificil":"cable-fly","sin_material":"push-up","vista_animacion":"frontal","seguridad":null}'::jsonb),
('push-up','{"id":"push-up","nombre":"Flexiones","musculo_principal":"Pectoral mayor","musculos_secundarios":["Tríceps","Deltoides anterior","Core"],"nivel":"principiante","preparacion":"Manos algo más anchas que los hombros, a la altura del pecho. Cuerpo recto de talones a cabeza; si cuesta, apoya las manos en un banco.","fases":[{"fase":"Baja","cue":"Pecho hacia el suelo, codos a unos 45 grados."},{"fase":"Empuja","cue":"Aleja el suelo hasta estirar los brazos."}],"respiracion":"Coge aire al bajar, suéltalo al empujar.","errores":["Cadera caída: aprieta glúteos y abdomen.","Codos en cruz: llévalos hacia atrás, a unos 45 grados.","Bajar a medias: pecho a un puño del suelo."],"mas_facil":null,"mas_dificil":"dips-chest","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('ab-wheel','{"id":"ab-wheel","nombre":"Rueda abdominal","musculo_principal":"Recto abdominal","musculos_secundarios":["Transverso del abdomen","Oblicuos","Dorsal ancho","Flexores de cadera"],"nivel":"intermedio","preparacion":"De rodillas sobre una esterilla, rueda bajo los hombros. Pelvis metida y abdomen firme, como si fueras a recibir un golpe.","fases":[{"fase":"Rueda","cue":"Avanza despacio sin que la cadera se hunda."},{"fase":"Vuelve","cue":"Tira de vuelta con el abdomen, cuerpo en bloque."}],"respiracion":"Coge aire antes de salir, suéltalo al volver.","errores":["Lumbar hundida: acorta el recorrido hasta donde mantengas la pelvis metida.","Sacar la cadera atrás al volver: vuelve con el cuerpo en bloque.","Ir demasiado lejos demasiado pronto: gana unos centímetros cada semana."],"mas_facil":"plank","mas_dificil":null,"sin_material":"plank","vista_animacion":"lateral","seguridad":"El recorrido lo marca tu control, no el suelo; si notas la lumbar, acórtalo."}'::jsonb),
('cable-crunch','{"id":"cable-crunch","nombre":"Crunch en polea","musculo_principal":"Recto abdominal","musculos_secundarios":["Oblicuos"],"nivel":"principiante","preparacion":"De rodillas frente a la polea alta, cuerda a los lados de la cabeza. Cadera quieta y un poco atrás.","fases":[{"fase":"Enrolla","cue":"Lleva el pecho hacia la pelvis, redondeando la espalda."},{"fase":"Vuelve","cue":"Sube despacio hasta estirar el abdomen, sin soltar tensión."}],"respiracion":"Suelta todo el aire al enrollar.","errores":["Tirar con los brazos: manos fijas junto a la cabeza.","Sentarte atrás con la cadera: la cadera no se mueve, se dobla la columna.","Demasiado peso: carga que te deje enrollar la espalda, no solo inclinarte."],"mas_facil":"crunch-abdominal","mas_dificil":null,"sin_material":"crunch-abdominal","vista_animacion":"lateral","seguridad":null}'::jsonb),
('crunch-abdominal','{"id":"crunch-abdominal","nombre":"Crunch abdominal","musculo_principal":"Recto abdominal","musculos_secundarios":["Oblicuos"],"nivel":"principiante","preparacion":"Boca arriba, rodillas dobladas y pies apoyados. Manos junto a las sienes o cruzadas en el pecho.","fases":[{"fase":"Sube","cue":"Despega los omóplatos del suelo, costillas hacia la pelvis."},{"fase":"Baja","cue":"Despacio, sin dejar caer la cabeza."}],"respiracion":"Suelta el aire al subir.","errores":["Tirar del cuello con las manos: apóyalas, no tires.","Subir hasta sentarte: basta con despegar los omóplatos.","Ir rápido: sube en un segundo, baja en dos."],"mas_facil":null,"mas_dificil":"decline-crunch","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('decline-crunch','{"id":"decline-crunch","nombre":"Crunch declinado","musculo_principal":"Recto abdominal","musculos_secundarios":["Oblicuos","Flexores de cadera"],"nivel":"intermedio","preparacion":"Banco declinado con los pies bien sujetos bajo los rodillos. Manos junto a las sienes o cruzadas en el pecho.","fases":[{"fase":"Sube","cue":"Enrolla la espalda vértebra a vértebra."},{"fase":"Baja","cue":"Controlado, hasta apoyar la zona lumbar, sin tumbarte del todo."}],"respiracion":"Suelta el aire al subir.","errores":["Subir con la espalda recta: eso es cadera; enrolla la columna.","Tirar del cuello: manos apoyadas, mirada al techo.","Dejarte caer: baja en dos o tres segundos."],"mas_facil":"crunch-abdominal","mas_dificil":"cable-crunch","sin_material":"crunch-abdominal","vista_animacion":"lateral","seguridad":null}'::jsonb),
('hanging-leg-raise','{"id":"hanging-leg-raise","nombre":"Elevación de piernas colgado","musculo_principal":"Recto abdominal","musculos_secundarios":["Flexores de cadera","Oblicuos","Antebrazo (agarre)"],"nivel":"intermedio","preparacion":"Cuélgate de la barra con los hombros activos y las piernas juntas. Si cuesta, empieza con las rodillas dobladas.","fases":[{"fase":"Sube","cue":"Eleva las piernas y enrolla la pelvis hacia arriba."},{"fase":"Baja","cue":"Despacio, sin balanceo."}],"respiracion":"Suelta el aire al subir.","errores":["Balanceo: pausa abajo y arranca desde parado.","Subir solo con la cadera: al final, enrolla la pelvis hacia el pecho.","Bajar de golpe: controla la bajada en dos segundos."],"mas_facil":null,"mas_dificil":null,"sin_material":"crunch-abdominal","vista_animacion":"lateral","seguridad":null}'::jsonb),
('l-sit','{"id":"l-sit","nombre":"L-sit (apoyo en paralelas)","musculo_principal":"Recto abdominal","musculos_secundarios":["Flexores de cadera","Cuádriceps","Tríceps","Trapecio inferior"],"nivel":"avanzado","preparacion":"Manos en las paralelas, brazos estirados y hombros empujando hacia abajo. Sube las piernas al frente hasta dejarlas paralelas al suelo.","fases":[{"fase":"Colócate","cue":"Brazos bloqueados, hombros lejos de las orejas."},{"fase":"Aguanta","cue":"Piernas estiradas y juntas a la altura de la cadera; si no llegas, dobla las rodillas."},{"fase":"Sal","cue":"Baja los pies al suelo con control."}],"respiracion":"Respira corto y continuo; no aguantes el aire.","errores":["Hombros hundidos: empuja las paralelas hacia abajo.","Piernas que caen: dobla las rodillas antes que perder la altura.","Espalda muy redonda: pecho alto, mirada al frente."],"mas_facil":"plank","mas_dificil":null,"sin_material":"plank","vista_animacion":"lateral","seguridad":null}'::jsonb),
('plank','{"id":"plank","nombre":"Plancha","musculo_principal":"Recto abdominal","musculos_secundarios":["Transverso del abdomen","Oblicuos","Glúteo mayor","Deltoides"],"nivel":"principiante","preparacion":"Antebrazos en el suelo con los codos bajo los hombros. Cuerpo recto de talones a cabeza.","fases":[{"fase":"Colócate","cue":"Aprieta glúteos y abdomen, mete un poco la pelvis."},{"fase":"Aguanta","cue":"Empuja el suelo con los antebrazos; cuerpo como una tabla."},{"fase":"Sal","cue":"Apoya las rodillas antes de perder la postura."}],"respiracion":"Respira corto y continuo, sin soltar el abdomen.","errores":["Cadera caída: aprieta glúteos y mete la pelvis.","Cadera muy alta: baja hasta la línea hombros-talones.","Aguantar con mala postura: mejor 20 segundos buenos que 60 malos."],"mas_facil":null,"mas_dificil":"ab-wheel","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('side-plank','{"id":"side-plank","nombre":"Plancha lateral","musculo_principal":"Oblicuos","musculos_secundarios":["Transverso del abdomen","Cuadrado lumbar","Glúteo medio"],"nivel":"principiante","preparacion":"De lado, codo bajo el hombro y piernas estiradas una sobre otra. Si cuesta, apoya la rodilla de abajo.","fases":[{"fase":"Sube","cue":"Eleva la cadera hasta alinear tobillo, cadera y hombro."},{"fase":"Aguanta","cue":"Cadera arriba y pecho abierto."},{"fase":"Sal","cue":"Baja la cadera con control y cambia de lado."}],"respiracion":"Respira corto y continuo; no aguantes el aire.","errores":["Cadera caída: súbela hasta la línea del cuerpo.","Cuerpo girado hacia el suelo: pecho y cadera mirando al frente.","Hombro hundido: empuja el suelo con el antebrazo."],"mas_facil":"plank","mas_dificil":null,"sin_material":null,"vista_animacion":"frontal","seguridad":null}'::jsonb),
('glute-bridge','{"id":"glute-bridge","nombre":"Puente de glúteo","musculo_principal":"Glúteo mayor","musculos_secundarios":["Isquiotibiales","Erectores espinales"],"nivel":"principiante","preparacion":"Boca arriba, rodillas dobladas y pies a la anchura de cadera, talones cerca del glúteo. Brazos a los lados.","fases":[{"fase":"Sube","cue":"Empuja con los talones hasta alinear rodillas, cadera y hombros."},{"fase":"Aguanta","cue":"Aprieta glúteos un segundo arriba."},{"fase":"Baja","cue":"Controlado, sin dejarte caer."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Arquear la lumbar arriba: costillas abajo, sube solo hasta la línea.","Empujar con las puntas: peso en los talones.","Rodillas hacia dentro: mantenlas en la línea de los pies."],"mas_facil":null,"mas_dificil":"hip-thrust","sin_material":null,"vista_animacion":"lateral","seguridad":null}'::jsonb),
('hip-thrust','{"id":"hip-thrust","nombre":"Hip thrust","musculo_principal":"Glúteo mayor","musculos_secundarios":["Isquiotibiales","Cuádriceps","Aductores"],"nivel":"intermedio","preparacion":"Espalda alta apoyada en el borde del banco, barra con almohadilla sobre la cadera. Pies a la anchura de cadera, colocados para que las tibias queden verticales arriba.","fases":[{"fase":"Sube","cue":"Empuja con los talones hasta alinear tronco y muslos."},{"fase":"Aguanta","cue":"Barbilla hacia el pecho, glúteos apretados un segundo."},{"fase":"Baja","cue":"Controlado, sin apoyar la barra del todo."}],"respiracion":"Coge aire y aprieta el abdomen antes de subir; suéltalo arriba.","errores":["Arquear la lumbar arriba: costillas abajo y barbilla al pecho.","Pies mal colocados: arriba, las tibias deben quedar verticales.","Subir a medias: extiende la cadera del todo."],"mas_facil":"glute-bridge","mas_dificil":null,"sin_material":"glute-bridge","vista_animacion":"lateral","seguridad":"Usa almohadilla en la barra y un banco estable que no se deslice."}'::jsonb),
('good-morning','{"id":"good-morning","nombre":"Buenos días con barra","musculo_principal":"Isquiotibiales","musculos_secundarios":["Erectores espinales","Glúteo mayor"],"nivel":"avanzado","preparacion":"Barra sobre la espalda alta, como en la sentadilla. Pies a la anchura de cadera, rodillas suaves y abdomen firme.","fases":[{"fase":"Baja","cue":"Cadera atrás e inclina el tronco con la espalda neutra."},{"fase":"Sube","cue":"Empuja la cadera adelante hasta quedar de pie."}],"respiracion":"Coge aire y bloquea el tronco antes de bajar; suéltalo arriba.","errores":["Redondear la espalda: baja solo hasta donde mantengas la columna neutra.","Doblar las rodillas como en una sentadilla: rodillas suaves y fijas, el movimiento es de cadera.","Cargar demasiado: aquí manda la técnica; empieza muy ligero."],"mas_facil":"back-extension","mas_dificil":null,"sin_material":"glute-bridge","vista_animacion":"lateral","seguridad":"Carga mucho la zona lumbar: empieza con la barra vacía y para si notas dolor en la espalda baja."}'::jsonb),
('lying-leg-curl','{"id":"lying-leg-curl","nombre":"Curl femoral tumbado","musculo_principal":"Isquiotibiales","musculos_secundarios":["Gemelos"],"nivel":"principiante","preparacion":"Boca abajo, rodillas justo fuera del borde del banco y rodillo sobre los tobillos. Cadera pegada al banco.","fases":[{"fase":"Sube","cue":"Lleva los talones hacia el glúteo."},{"fase":"Baja","cue":"Estira las piernas despacio, sin bloquear."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Levantar la cadera del banco: cadera pegada; baja el peso.","Bajar de golpe: dos o tres segundos en la bajada.","Rodillo mal colocado: sobre los tobillos, no en los gemelos."],"mas_facil":null,"mas_dificil":"romanian-deadlift","sin_material":"glute-bridge","vista_animacion":"lateral","seguridad":null}'::jsonb),
('romanian-deadlift','{"id":"romanian-deadlift","nombre":"Peso muerto rumano","musculo_principal":"Isquiotibiales","musculos_secundarios":["Glúteo mayor","Erectores espinales","Antebrazo (agarre)"],"nivel":"intermedio","preparacion":"De pie con la barra en las manos, agarre a la anchura de hombros. Pies a la anchura de cadera y rodillas suaves.","fases":[{"fase":"Baja","cue":"Cadera atrás, barra pegada a las piernas, espalda neutra."},{"fase":"Sube","cue":"Empuja la cadera adelante y aprieta glúteos arriba."}],"respiracion":"Coge aire arriba y bloquea el tronco; suéltalo al terminar de subir.","errores":["Espalda redonda: baja solo hasta donde la mantengas neutra, normalmente algo bajo la rodilla.","Barra lejos del cuerpo: que roce los muslos todo el recorrido.","Convertirlo en sentadilla: rodillas casi fijas, el movimiento es de cadera."],"mas_facil":"back-extension","mas_dificil":"good-morning","sin_material":"glute-bridge","vista_animacion":"lateral","seguridad":"Si la espalda se redondea, reduce el recorrido o el peso."}'::jsonb),
('air-squat','{"id":"air-squat","nombre":"Sentadilla peso corporal","musculo_principal":"Cuádriceps","musculos_secundarios":["Glúteo mayor","Aductores","Core"],"nivel":"principiante","preparacion":"Pies algo más anchos que la cadera, puntas ligeramente hacia fuera. Brazos al frente para equilibrarte.","fases":[{"fase":"Baja","cue":"Cadera atrás y abajo, rodillas en la línea de los pies."},{"fase":"Sube","cue":"Empuja el suelo con todo el pie hasta quedar de pie."}],"respiracion":"Coge aire al bajar, suéltalo al subir.","errores":["Rodillas hacia dentro: empújalas hacia fuera, en la línea de los pies.","Talones despegados: peso repartido en todo el pie.","Espalda que se redondea abajo: baja hasta donde mantengas el pecho alto."],"mas_facil":null,"mas_dificil":"back-squat","sin_material":null,"vista_animacion":"ambas","seguridad":null}'::jsonb),
