('bulgarian-split-squat','{"id":"bulgarian-split-squat","nombre":"Sentadilla búlgara","musculo_principal":"Cuádriceps","musculos_secundarios":["Glúteo mayor","Aductores","Isquiotibiales"],"nivel":"intermedio","preparacion":"Empeine del pie de atrás sobre un banco, pie de delante a un paso largo. Mancuernas a los lados.","fases":[{"fase":"Baja","cue":"En vertical, hasta que la rodilla de atrás casi toque el suelo."},{"fase":"Sube","cue":"Empuja con el pie de delante, todo el pie apoyado."}],"respiracion":"Coge aire al bajar, suéltalo al subir.","errores":["Pie de delante demasiado cerca: aléjalo hasta que el talón no se despegue al bajar.","Rodilla hacia dentro: en la línea del pie.","Empujar con la pierna de atrás: es solo apoyo; trabaja la de delante."],"mas_facil":"walking-lunge","mas_dificil":null,"sin_material":"air-squat","vista_animacion":"ambas","seguridad":null}'::jsonb),
