('dumbbell-shoulder-press','{"id":"dumbbell-shoulder-press","nombre":"Press hombro con mancuernas","musculo_principal":"Deltoides anterior","musculos_secundarios":["Deltoides lateral","Tríceps","Trapecio superior"],"nivel":"principiante","preparacion":"Sentado con el respaldo casi vertical, o de pie. Mancuernas a la altura de los hombros, codos un poco por delante del cuerpo.","fases":[{"fase":"Empuja","cue":"Sube hasta estirar los brazos sobre la cabeza."},{"fase":"Baja","cue":"Hasta la altura de las orejas o algo más, controlando."}],"respiracion":"Suelta el aire al empujar, cógelo al bajar.","errores":["Arquear la lumbar: aprieta abdomen y glúteos; baja el peso.","Codos en cruz: adelántalos un poco.","Chocar las mancuernas arriba: júntalas sin golpe."],"mas_facil":null,"mas_dificil":"overhead-press","sin_material":"push-up","vista_animacion":"frontal","seguridad":null}'::jsonb),
('face-pull','{"id":"face-pull","nombre":"Face pull en polea","musculo_principal":"Deltoides posterior","musculos_secundarios":["Trapecio medio","Trapecio inferior","Romboides","Manguito rotador"],"nivel":"principiante","preparacion":"Polea a la altura de la cara o algo más alta, con cuerda. Agarre con los pulgares hacia ti, un paso atrás y brazos estirados.","fases":[{"fase":"Tira","cue":"Cuerda hacia la cara separando las manos, codos altos."},{"fase":"Abre","cue":"Al final, gira: puños junto a las orejas."},{"fase":"Vuelve","cue":"Estira los brazos despacio."}],"respiracion":"Suelta el aire al tirar, cógelo al volver.","errores":["Codos bajos: a la altura de los hombros o por encima.","Echarte atrás para tirar: tronco quieto; baja el peso.","Demasiado peso: aquí manda el control; aprieta la espalda alta."],"mas_facil":null,"mas_dificil":null,"sin_material":null,"vista_animacion":"ambas","seguridad":null}'::jsonb),
('lateral-raise','{"id":"lateral-raise","nombre":"Elevaciones laterales","musculo_principal":"Deltoides lateral","musculos_secundarios":["Trapecio superior","Deltoides anterior"],"nivel":"principiante","preparacion":"De pie, mancuernas a los lados y codos ligeramente doblados. Tronco un poco inclinado hacia delante.","fases":[{"fase":"Sube","cue":"Eleva los brazos hacia los lados hasta la altura de los hombros."},{"fase":"Baja","cue":"Despacio, sin dejar caer."}],"respiracion":"Suelta el aire al subir, cógelo al bajar.","errores":["Encoger los hombros al subir: para a la altura del hombro, hombros abajo.","Balancear el cuerpo: tronco quieto, menos peso.","Subir con las manos por delante: lidera con los codos."],"mas_facil":null,"mas_dificil":null,"sin_material":null,"vista_animacion":"frontal","seguridad":null}'::jsonb),
('overhead-press','{"id":"overhead-press","nombre":"Press militar con barra","musculo_principal":"Deltoides anterior","musculos_secundarios":["Deltoides lateral","Tríceps","Trapecio superior","Core"],"nivel":"intermedio","preparacion":"Barra sobre la parte alta del pecho, agarre algo más ancho que los hombros. Pies a la anchura de cadera, glúteos y abdomen apretados.","fases":[{"fase":"Empuja","cue":"Sube la barra en línea recta, apartando la cara."},{"fase":"Pasa","cue":"Cuando pase la frente, mete la cabeza bajo la barra."},{"fase":"Bloquea","cue":"Brazos estirados, barra sobre la mitad del pie."}],"respiracion":"Coge aire y aprieta el abdomen antes de empujar; suéltalo arriba.","errores":["Arquear la lumbar: glúteos y abdomen apretados, costillas abajo.","Barra por delante de la cabeza al final: termina con la barra sobre la cabeza.","Empujar con las piernas: rodillas estiradas y quietas."],"mas_facil":"dumbbell-shoulder-press","mas_dificil":null,"sin_material":"push-up","vista_animacion":"lateral","seguridad":null}'::jsonb),
('dips-tricep','{"id":"dips-tricep","nombre":"Fondos para tríceps","musculo_principal":"Tríceps","musculos_secundarios":["Pectoral mayor","Deltoides anterior"],"nivel":"intermedio","preparacion":"En paralelas, brazos estirados y hombros abajo. Tronco vertical y codos pegados al cuerpo.","fases":[{"fase":"Baja","cue":"Dobla los codos hacia atrás hasta unos 90 grados."},{"fase":"Empuja","cue":"Estira los brazos del todo."}],"respiracion":"Coge aire al bajar, suéltalo al empujar.","errores":["Inclinar el tronco: vertical, así trabaja más el tríceps.","Codos abiertos: apúntalos hacia atrás.","Bajar demasiado: para en unos 90 grados de codo."],"mas_facil":"push-up","mas_dificil":null,"sin_material":"push-up","vista_animacion":"lateral","seguridad":"Si notas molestia en la parte delantera del hombro, reduce el recorrido."}'::jsonb),
('skull-crusher','{"id":"skull-crusher","nombre":"Press francés","musculo_principal":"Tríceps","musculos_secundarios":[],"nivel":"intermedio","preparacion":"Tumbado en un banco, barra Z sobre el pecho con agarre algo más estrecho que los hombros. Brazos estirados y un poco inclinados hacia la cabeza.","fases":[{"fase":"Baja","cue":"Dobla solo los codos y lleva la barra hacia la frente o justo detrás de la cabeza."},{"fase":"Sube","cue":"Estira los codos sin mover los brazos."}],"respiracion":"Coge aire al bajar, suéltalo al subir.","errores":["Abrir los codos: apúntalos al techo, paralelos.","Mover los hombros: brazos fijos, solo se mueve el codo.","Bajar sin control: dos o tres segundos, con una carga que manejes."],"mas_facil":"tricep-pushdown-rope","mas_dificil":null,"sin_material":"push-up","vista_animacion":"lateral","seguridad":"Empieza ligero y baja siempre controlado; si notas el codo, pasa a polea."}'::jsonb),
('tricep-pushdown-bar','{"id":"tricep-pushdown-bar","nombre":"Jalón tríceps con barra","musculo_principal":"Tríceps","musculos_secundarios":[],"nivel":"principiante","preparacion":"Polea alta con barra recta o en V. Codos pegados a los costados, tronco un poco inclinado.","fases":[{"fase":"Empuja","cue":"Baja la barra hasta estirar los brazos del todo."},{"fase":"Vuelve","cue":"Sube hasta que los antebrazos queden paralelos al suelo, codos quietos."}],"respiracion":"Suelta el aire al empujar, cógelo al volver.","errores":["Codos que se separan o suben: pegados al cuerpo.","Cargar con el cuerpo: tronco quieto, menos peso.","Recorrido corto: estira del todo abajo."],"mas_facil":null,"mas_dificil":"skull-crusher","sin_material":"push-up","vista_animacion":"lateral","seguridad":null}'::jsonb),
('tricep-pushdown-rope','{"id":"tricep-pushdown-rope","nombre":"Tríceps polea con cuerda","musculo_principal":"Tríceps","musculos_secundarios":[],"nivel":"principiante","preparacion":"Polea alta con cuerda y agarre neutro. Codos pegados a los costados.","fases":[{"fase":"Empuja","cue":"Baja y separa las manos al final, brazos estirados."},{"fase":"Vuelve","cue":"Sube controlado hasta que los antebrazos queden paralelos al suelo."}],"respiracion":"Suelta el aire al empujar, cógelo al volver.","errores":["Codos que se adelantan: fijos junto al cuerpo.","Cargar con el cuerpo: tronco quieto, menos peso.","No separar la cuerda al final: abre las manos para estirar del todo."],"mas_facil":null,"mas_dificil":"skull-crusher","sin_material":"push-up","vista_animacion":"lateral","seguridad":null}'::jsonb)
